import{_ as o,a0 as r,w as p,s as d,I as e,x as s,a1 as a,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"匿名上网：学习在 Linux 上安装 TOR 网络 | LCTT x X-CMD","titleTemplate":false,"description":"匿名上网：学习在 Linux 上安装 TOR 网络 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"匿名上网：学习在 Linux 上安装 TOR 网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"匿名上网：学习在 Linux 上安装 TOR 网络 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171219 Surf anonymously- Learn to install TOR network on Linux","title":"匿名上网：学习在 Linux 上安装 TOR 网络","tag":"201801","desc":""},"relativePath":"201801/20171219 Surf anonymously- Learn to install TOR network on Linux.md","filePath":"[post].md"}'),u={name:"201801/20171219 Surf anonymously- Learn to install TOR network on Linux.md"};function h(g,t,b,k,c,f){const i=r("Link");return p(),d("div",null,[t[18]||(t[18]=e("h1",{id:"匿名上网-学习在-linux-上安装-tor-网络",tabindex:"-1"},[s("匿名上网：学习在 Linux 上安装 TOR 网络 "),e("a",{class:"header-anchor",href:"#匿名上网-学习在-linux-上安装-tor-网络","aria-label":"Permalink to “匿名上网：学习在 Linux 上安装 TOR 网络”"},"​")],-1)),t[19]||(t[19]=e("p",null,"Tor 网络是一个用来保护你的互联网以及隐私的匿名网络。Tor 网络是一组志愿者运营的服务器。Tor 通过在由志愿者运营的分布式中继系统之间跳转来保护互联网通信。这避免了人们窥探我们的网络，他们无法了解我们访问的网站或者用户身在何处，并且也可以让我们访问被屏蔽的网站。",-1)),t[20]||(t[20]=e("p",null,"在本教程中，我们将学习在各种 Linux 操作系统上安装 Tor 网络，以及如何使用它来配置我们的程序来保护通信。",-1)),e("p",null,[t[1]||(t[1]=s("推荐阅读：",-1)),a(i,{href:"http://linuxtechlab.com/install-tor-browser-linux-ubuntu-centos/"},{default:n(()=>[...t[0]||(t[0]=[s("如何在 Linux 上安装 Tor 浏览器（Ubuntu、Mint、RHEL、Fedora、CentOS）",-1)])]),_:1})]),t[21]||(t[21]=l(`<h3 id="centos-rhel-fedora" tabindex="-1">CentOS/RHEL/Fedora <a class="header-anchor" href="#centos-rhel-fedora" aria-label="Permalink to “CentOS/RHEL/Fedora”">​</a></h3><p>Tor 包是 EPEL 仓库的一部分，所以如果我们安装了 EPEL 仓库，我们可以直接使用 <code>yum</code> 来安装 Tor。如果你需要在您的系统上安装 EPEL 仓库，请使用下列适当的命令（基于操作系统和体系结构）：</p><p>RHEL/CentOS 7：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh https://dl.fedoraproject.org/pub/epel/7/x86_64/e/epel-release-7-11.noarch.rpm</span></span></code></pre></div><p>RHEL/CentOS 6 (64 位)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh http://download.fedoraproject.org/pub/epel/6/x86_64/epel-release-6-8.noarch.rpm</span></span></code></pre></div><p>RHEL/CentOS 6 (32 位)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh http://dl.fedoraproject.org/pub/epel/6/i386/epel-release-6-8.noarch.rpm</span></span></code></pre></div><p>安装完成后，我们可以用下面的命令安装 Tor 浏览器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tor</span></span></code></pre></div><h3 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to “Ubuntu”">​</a></h3><p>为了在 Ubuntu 机器上安装 Tor 网络，我们需要添加官方 Tor 仓库。我们需要将仓库信息添加到 <code>/etc/apt/sources.list</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/apt/sources.list</span></span></code></pre></div><p>现在根据你的操作系统添加下面的仓库信息：</p><p>Ubuntu 16.04：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://deb.torproject.org/torproject.org xenial main</span></span>
<span class="line"><span>deb-src http://deb.torproject.org/torproject.org xenial main</span></span></code></pre></div><p>Ubuntu 14.04</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://deb.torproject.org/torproject.org trusty main</span></span>
<span class="line"><span>deb-src http://deb.torproject.org/torproject.org trusty main</span></span></code></pre></div><p>接下来打开终端并执行以下两个命令添加用于签名软件包的 gpg 密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -keyserver keys.gnupg.net -recv A3C4F0F979CAA22CDBA8F512EE8CBC9E886DDD89</span></span>
<span class="line"><span>$ gpg -export A3C4F0F979CAA22CDBA8F512EE8CBC9E886DDD89 | sudo apt-key add -</span></span></code></pre></div><p>现在运行更新并安装 Tor 网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install tor deb.torproject.org-keyring</span></span></code></pre></div><h3 id="debian" tabindex="-1">Debian <a class="header-anchor" href="#debian" aria-label="Permalink to “Debian”">​</a></h3><p>我们可以无需添加任何仓库在 Debian 上安装 Tor 网络。只要打开终端并以 root 身份执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt install tor</span></span></code></pre></div><h3 id="tor-配置" tabindex="-1">Tor 配置 <a class="header-anchor" href="#tor-配置" aria-label="Permalink to “Tor 配置”">​</a></h3>`,26)),e("p",null,[t[3]||(t[3]=s("如果你最终目的只是为了保护互联网浏览，而没有其他要求，直接使用 Tor 更好，但是如果你需要保护即时通信、IRC、Jabber 等程序，则需要配置这些应用程序进行安全通信。但在做之前，让我们先看看",-1)),a(i,{href:"https://www.torproject.org/download/download.html.en#warning"},{default:n(()=>[...t[2]||(t[2]=[s("Tor 网站上提到的警告",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[22]||(t[22]=l('<ul><li>不要大流量使用 Tor</li><li>不要在 Tor 中使用任何浏览器插件</li><li>只使用 HTTPS 版本的网站</li><li>不要在线打开通过 Tor 下载的任何文档。</li><li>尽可能使用 Tor 桥</li></ul><p>现在配置程序来使用 Tor，例如 jabber。首先选择 “SOCKS代理” 而不是使用 HTTP 代理，并使用端口号 <code>9050</code>，或者也可以使用端口 9150（Tor 浏览器使用）。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/12/tor-1-compressor.png?resize=333%2C240" alt="install tor network"></p><p>你也可以配置 Firefox 浏览器使用 Tor 网络。打开 Firefox 浏览器，在“常规”选项卡的“首选项”中进入“网络代理”设置，并按以下步骤输入代理：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2017/12/tor-2-compressor.png?resize=730%2C640" alt="install tor network"></p><p>现在你可以在 Firefox 中使用 Tor 网络完全匿名访问了。</p><p>这就是我们如何安装 Tor 网络并使用 Tor 浏览互联网的教程。请在下面的评论栏中提出你的问题和建议。</p><hr>',8)),e("p",null,[t[6]||(t[6]=s("via: ",-1)),a(i,{href:"http://linuxtechlab.com/learn-install-tor-network-linux/"},{default:n(()=>[...t[5]||(t[5]=[s("http://linuxtechlab.com/learn-install-tor-network-linux/",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=s("作者：",-1)),a(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>[...t[7]||(t[7]=[s("Shusain",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[8]||(t[8]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const C=o(u,[["render",h]]);export{x as __pageData,C as default};
